ee:variables.ee:set-variable:
%dw 2.0
output application/xml
ns soap http://www.w3.org/2003/05/soap-envelope
ns mdm http://www.etb.com.co/Gateway/MDM_Logic_Services_V2
fun appendNamespace(data, nsSelector) =
  data match {
    case is Array -> data map appendNamespace($, nsSelector)
    case is Object -> data mapObject do {
      var ns0 = nsSelector
      ---
      if (ns0 != null) ns0#"$($$)": appendNamespace($, nsSelector)
      else ($$): appendNamespace($, nsSelector)
    }
    else -> data
}
---
{
    soap#Envelope: {
        soap#Header: null,
        soap#Body: {
            mdm#Portabilidad_Saliente_1002: {
                mdm#WSRequestHeader: {
                    mdm#system: {
                        mdm#name: "MULESOFT-PORTABILIDAD",
					    mdm#correlationId: payload.MensajeABD.CabeceraMensaje.IdentificadorProceso,
					    mdm#processingServer: "Mulesoft Prod"
                    }
                },
                mdm#WSRequestBody: {
                    (mdm#DireccionAbonado: payload.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.DireccionAbonado) if (!isBlank(payload.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.DireccionAbonado)),
                    mdm#FechaCreacionMensaje: payload.MensajeABD.CabeceraMensaje.FechaCreacionMsg,
                    mdm#IdMensaje: payload.MensajeABD.CabeceraMensaje.IdentificadorMensaje,
                    mdm#IdOperadorEmisor: payload.MensajeABD.CabeceraMensaje.Emisor,
                    mdm#IdProceso: payload.MensajeABD.CabeceraMensaje.IdentificadorProceso,
                    (mdm#NRN: payload.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.NRN) if (!isBlank(payload.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.NRN)),
                    (mdm#NombreAbonado: payload.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.NombreRazonSocialAbonado) if (!isBlank(payload.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.NombreRazonSocialAbonado)),
                    (mdm#Numeracion: payload.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.ListaNumeracionNip.NumeracionNip[0].Numero) if (!isBlank(payload.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.ListaNumeracionNip.NumeracionNip[0].Numero)),
                    (mdm#NumeroIdentidad: payload.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.IdentificacionAbonado) if (!isBlank(payload.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.IdentificacionAbonado)),
                    (mdm#OperadorDonante: payload.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.Donante) if (!isBlank(payload.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.Donante)),
                    (mdm#SolicitudRealizadaXTercero: payload.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.SolicitudTerceros) if (!isBlank(payload.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.SolicitudTerceros)),
                    mdm#TipoMensaje: payload.MensajeABD.CabeceraMensaje.TipoMsg,
                    (mdm#TipoServicio: payload.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.TipoServicio) if (!isBlank(payload.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.TipoServicio)),
                    (mdm#TipoUsuario: payload.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.TipoUsuario) if (!isBlank(payload.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.TipoUsuario)),
                    (mdm#DocumentoID: payload.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.DocumentoID) if (!isBlank(payload.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.DocumentoID)),
                    (mdm#DocumentoAT: payload.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.DocumentoAT) if (!isBlank(payload.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.DocumentoAT)),
                    (mdm#DocumentoCC: payload.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.DocumentoCC) if (!isBlank(payload.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.DocumentoCC)),
                    (mdm#TipoDocumentoIdentificacion: payload.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.TipoDocumentoIdentificacion) if (!isBlank(payload.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.TipoDocumentoIdentificacion)), 
                    (mdm#FechaExpedicionIdentificacion: payload.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.FechaExpedicionIdentificacion) if (!isBlank(payload.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.FechaExpedicionIdentificacion)), 
                    (mdm#TipoDocumentoIdentificacionRepresentanteLegal: payload.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.TipoDocumentoIdentificacionRepresentanteLegal) if (!isBlank(payload.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.TipoDocumentoIdentificacionRepresentanteLegal)),
                    (mdm#IdentificacionRepresentanteLegal: payload.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.IdentificacionRepresentanteLegal) if (!isBlank(payload.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.IdentificacionRepresentanteLegal)), 
                    (mdm#FechaExpedicionIdentificacionRepresentanteLegal: payload.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.FechaExpedicionIdentificacionRepresentanteLegal) if (!isBlank(payload.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.FechaExpedicionIdentificacionRepresentanteLegal)),      
                    mdm#ListaNumeracionNip: appendNamespace(payload.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.ListaNumeracionNip, mdm)
                }
            }
        }
    }
}
